theorem one_le_walkWeight_aboveAnchor {n : ℕ} {w : List Branch}
    (hn : 2 ≤ n) (h : AboveAnchor n w) {k : ℕ} (hk : k ≤ w.length) :
    1 ≤ walkWeight w k

theorem follows_log_le_walkWeight {n : ℕ} {w : List Branch}
    (hn : 1 ≤ n) (hf : follows n w) {k : ℕ} (hk : k ≤ w.length) :
    Real.log (floorPower^[k] n) ≤ walkWeight w k * Real.log n

theorem two_pow_le_walkWeight {w : List Branch} {k B : ℕ}
    (hB : 2 ^ (k + B) ≤ 3 ^ oddCount (w.take k)) :
    (2 : ℝ) ^ B ≤ walkWeight w k

theorem smoothSet_eq_integral (H : ℕ) {S : Set UnitAddCircle}
    (hS : MeasurableSet S) (x : UnitAddCircle) :
    smoothSet H S x = ∫ t in S, kernel H (x-t)

theorem product_difference {x y z u v w : ℝ}
    (hx : 0 ≤ x ∧ x ≤ 1) (hy : 0 ≤ y ∧ y ≤ 1) (_hz : 0 ≤ z ∧ z ≤ 1)
    (_hu : 0 ≤ u ∧ u ≤ 1) (hv : 0 ≤ v ∧ v ≤ 1) (hw : 0 ≤ w ∧ w ≤ 1) :

theorem chain_difference {f : ℕ → ℝ → ℝ} {r : ℕ} {a b h : ℝ}
    (hf : Chain f (r+1) a b) (hh : 0 ≤ h) :
    Chain (fun j => difference h (f j)) r a (b-h)

theorem small_cutoff_bound (f : ℕ → ℝ) (N : ℕ) {q K : ℝ}
    (hq0 : 0 < q) (hq1 : q ≤ 1) (hK : 1 ≤ K) :
    ‖∑ n ∈ range N, phase (f n)‖ ≤ K*N/Real.sqrt q

theorem tendsto_intermediate_rpow_ratio {t : ℝ → ℝ} {h : ℝ}
    (ht : ∀ᶠ x in atTop, x ≤ t x ∧ t x ≤ x + h) (p : ℝ) :
    Tendsto (fun x => (t x) ^ p / x ^ p) atTop (𝓝 1)

theorem HasPowerAsymptotics.difference {f : ℝ → ℝ} {p c h : ℝ}
    (hf : HasPowerAsymptotics f p c) (hh : 0 < h) :
    HasPowerAsymptotics (fun x => f (x + h) - f x) (p - 1) (h * c * p)

theorem HasPowerAsymptotics.cancellation_sublinear_pos {f : ℝ → ℝ} {p c : ℝ}
    (hf : HasPowerAsymptotics f p c) (hp : 0 < p) (hp1 : p < 1) (hc : 0 < c) :
    Tendsto (average (fun n => phase (f n))) atTop (𝓝 0)

theorem HasPowerAsymptotics.lower_order {f : ℝ → ℝ} {p q c : ℝ}
    (hf : HasPowerAsymptotics f p c) (hpq : p < q) :
    HasPowerAsymptotics f q 0

theorem HasPowerAsymptotics.add {f g : ℝ → ℝ} {p c d : ℝ}
    (hf : HasPowerAsymptotics f p c) (hg : HasPowerAsymptotics g p d) :
    HasPowerAsymptotics (fun x => f x + g x) p (c + d)

theorem HasPowerAsymptotics.affine {f : ℝ → ℝ} {p c A : ℝ}
    (hf : HasPowerAsymptotics f p c) (hA : 0 < A) (B : ℝ) :
    HasPowerAsymptotics (fun x => f (A * x + B)) p (A ^ p * c)

def generationEquiv (f : α → α) (d : ℕ) (a : α) :
    (Σ b : {b : α // f b = a}, {x : α // f^[d] x = b.val}) ≃
      {x : α // f^[d+1] x = a}

theorem depth_unique (f : α → α) {a x : α}
    (ha : ∀ k : ℕ, 0 < k → f^[k] a ≠ a) {i j : ℕ}
    (hi : f^[i] x = a) (hj : f^[j] x = a) : i = j

def ancestorEquiv (f : α → α) (a : α)
    (ha : ∀ k : ℕ, 0 < k → f^[k] a ≠ a) :
    (Σ d : ℕ, {x : α // f^[d] x = a}) ≃ {x : α // ∃ d : ℕ, f^[d] x = a}

theorem tendsto_sublinear_power_average_pos {c θ : ℝ}
    (hc : 0 < c) (hθ : 0 < θ) (hθ1 : θ < 1) :
    Tendsto (average (fun n => phase (c * (n : ℝ) ^ θ))) atTop (𝓝 0)

theorem tendsto_sublinear_power_average {c θ : ℝ}
    (hc : c ≠ 0) (hθ : 0 < θ) (hθ1 : θ < 1) :
    Tendsto (average (fun n => phase (c * (n : ℝ) ^ θ))) atTop (𝓝 0)
